callGraph.callee:
[...canonicalById.values()]
    .filter((session) => {
      const pyq = pyqById.get(session.id);
      if (pyq) return pyq.status !== 'active' && attemptedPyqSessionIds.has(session.id);
      return session.actual_duration_min !== null && populatedSessionIds.has(session.id);
    })
    .sort

loadPyqManifest()
      .then((value) => {
        if (!active) return;
        setManifest(value);
        setConfig((current) => {
          const requestedSubject = searchParams.get('subject');
          const requested = requestedSubject
            ? value.subjects.find(
                (subject) =>
                  subject.label.toLocaleLowerCase() === requestedSubject.toLocaleLowerCase()
              )
            : null;
          return {
            ...current,
            subjectSlug: requested?.slug ?? current.subjectSlug,
            topicSlug: 'all',
            fromYear: value.firstYear,
            toYear: value.lastYear
          };
        });
      })
      .catch
